const {app,BrowserWindow}=require('electron');
const fs=require('node:fs/promises'),path=require('node:path'),assert=require('node:assert/strict');
const {pathToFileURL}=require('node:url');
const root=path.resolve(__dirname,'../..'),directory=process.env.SAS_CHECK_UI_QA_DIR;
const url=process.env.SAS_CHECK_UI_QA_URL;
assert.ok(url,'The Node test runner must start the isolated Vite server.');
assert.ok(directory);app.commandLine.appendSwitch('mute-audio');app.setPath('userData',path.join(directory,'profile'));app.on('window-all-closed',()=>{});
process.on('uncaughtException',error=>{console.error(error.stack||error);app.exit(1);});
process.on('unhandledRejection',error=>{console.error(error?.stack||error);app.exit(1);});
const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function until(fn){const end=Date.now()+12000;while(Date.now()<end){if(await fn())return;await pause(30);}throw Error('React adventure check UI timeout');}
app.whenReady().then(async()=>{
 let window;const proof={};
 try{
  const load=relative=>import(pathToFileURL(path.join(root,relative)).href),{createAdventureGame,adventureActor}=await load('server/adventure-engine.mjs'),{defaultAbilities}=await load('shared/srp.mjs');
  window=new BrowserWindow({show:false,width:1100,height:900,webPreferences:{nodeIntegration:false,contextIsolation:true}});window.webContents.setAudioMuted(true);const run=code=>window.webContents.executeJavaScript(`{${code}\n}`);window.webContents.on('console-message',(_event,_level,message)=>console.log(message));
  await window.loadURL(url);await until(()=>run('window.adventureReady===true'));
  const game=createAdventureGame('dnd'),persona={id:'sheet',name:'Герой',kind:'srp',className:'Воин',abilities:defaultAbilities(),inventory:[],spells:[]};game.actors=[adventureActor('host',persona,game.rules),{...adventureActor('merchant',{...persona,id:'merchant-sheet',name:'Торговец'},game.rules),player:false},adventureActor('guest',{...persona,id:'guest-sheet',name:'Другой герой'},game.rules)];game.order=['host','guest'];game.phase='players';game.challenges=[{id:'own',name:'Скидка',actorId:'host',targetId:'merchant',ability:'charisma',checkType:'persuasion',dc:15,intent:'Прошу снизить цену',actionId:'trade-1'},{id:'foreign',name:'Чужая проверка',actorId:'guest',ability:'wisdom',checkType:'perception',dc:10},{id:'common',name:'Сдвинуть гору',ability:'strength',checkType:'athletics',dc:1000,impossible:true,impossibleReason:'Гора превышает возможности героя',actionId:'mountain-1'}];
  await run(`window.game=${JSON.stringify(game)};renderAdventure();`);await until(()=>run("!!document.querySelector('[data-adventure-checks] select')"));
  proof.challengeIsolation=await run("JSON.stringify(Array.from(document.querySelector('[data-adventure-checks] select').options,o=>o.value))===JSON.stringify(['own','common'])&&document.querySelector('[data-adventure-checks]').textContent.includes('сложность 15')");
  await run("window.clickText=text=>Array.from(document.querySelectorAll('button')).find(b=>b.textContent===text)?.click();window.change=(node,value)=>{const owner=node.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:node.tagName==='SELECT'?HTMLSelectElement.prototype:HTMLInputElement.prototype;Object.getOwnPropertyDescriptor(owner,'value').set.call(node,value);node.dispatchEvent(new Event(node.tagName==='SELECT'?'change':'input',{bubbles:true}));};window.field=label=>Array.from(document.querySelectorAll('label')).find(n=>n.querySelector('.field-label')?.textContent===label)?.querySelector('input,textarea,select');delayAction=true;clickText('Бросить назначенную проверку');clickText('Бросить назначенную проверку');");await pause(30);
  proof.singleRoll=await run("checkActions.length===1&&checkActions[0].action==='check'&&checkActions[0].challengeId==='own'");await run("finishAction(true);delayAction=false;game.log.push({id:'result',text:'Герой: критический провал, натуральная 1.',calculation:{kind:'check',actorId:'host',challengeId:'own',actionId:'trade-1',roll:1,total:1,critical:'failure'}});renderAdventure();");await until(()=>run("Array.from(document.querySelectorAll('button')).some(b=>b.textContent==='Проверка уже выполнена'&&b.disabled)"));proof.completedRoll=await run("document.querySelector('[data-adventure-checks]').textContent.includes('критический провал')");
  await run("game.challenges[0].results={host:game.log.at(-1)};game.log=[];game.eventArchive=[];renderAdventure()");await pause(30);proof.resultSurvivesLogTruncation=await run("Array.from(document.querySelectorAll('button')).some(b=>b.textContent==='Проверка уже выполнена'&&b.disabled)&&document.querySelector('[data-adventure-checks]').textContent.includes('критический провал')");
  await run("change(field('Назначенное задание'),'common')");await pause(30);proof.impossibleVisible=await run("document.querySelector('[data-adventure-checks]').textContent.includes('Гора превышает возможности героя')");
  await run("change(field('Намерение'),'Пытаюсь сдвинуть валун с дороги');change(field('Навык или характеристика'),'athletics')");await pause(30);await run("clickText('Подготовить проверку')");await pause(30);proof.intentPayload=await run("checkActions.at(-1).action==='prepareCheck'&&checkActions.at(-1).checkType==='athletics'&&checkActions.at(-1).intent==='Пытаюсь сдвинуть валун с дороги'&&!('dc' in checkActions.at(-1))");
  await run("clickText('Бросить свободную проверку')");await pause(30);proof.freeCheckExplicit=await run("checkActions.at(-1).action==='check'&&checkActions.at(-1).freeCheck===true&&!checkActions.at(-1).challengeId");
  await run("game.order=['guest','host'];game.turn=0;game.actors.find(a=>a.id==='guest').online=false;renderAdventure()");await until(()=>run("Array.from(document.querySelectorAll('button')).some(b=>b.textContent==='Пропустить отсутствующего')"));await run("clickText('Пропустить отсутствующего')");await pause(30);proof.offlineHostSkip=await run("checkActions.at(-1).action==='end'&&checkActions.at(-1).actorId==='guest'");
  await run("clickText('Хост')");await until(()=>run("!!field('Настроить')"));await run("change(field('Название задания'),'Убрать валун');change(field('Намерение игрока'),'Освобождаю дорогу');change(field('Сложность'),'15')");await pause(30);await run("clickText('Сохранить задание')");await pause(30);proof.hostTaskPayload=await run("checkActions.at(-1).action==='setChallenge'&&checkActions.at(-1).challenge.dc===15&&checkActions.at(-1).challenge.name==='Убрать валун'");
  await run("change(field('Настроить'),'npc')");await pause(30);await run("change(field('NPC, существо или объект'),'merchant');change(field('Тип проверки'),'intimidation');change(field('Сложность'),'17')");await pause(30);await run("clickText('Сохранить сложность')");await pause(30);proof.hostNpcPayload=await run("checkActions.at(-1).action==='setCheckDifficulty'&&checkActions.at(-1).targetId==='merchant'&&checkActions.at(-1).checkType==='intimidation'&&checkActions.at(-1).difficulty.dc===17&&checkActions.at(-1).difficulty.ability==='charisma'");
  for(const [name,value]of Object.entries(proof))assert.equal(value,true,name);proof.success=true;
 }catch(error){proof.success=false;proof.error=error.stack;}
 finally{if(window&&!window.isDestroyed())window.destroy();await fs.writeFile(path.join(directory,'adventure-check-ui-proof.json'),JSON.stringify(proof,null,2));console.log(JSON.stringify(proof));app.exit(proof.success?0:1);}
});
